import{_ as l,a0 as r,w as s,s as d,ao as o,I as n,x as e,a1 as p,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"給那些懷舊的遊戲骨灰粉絲們：自制一台樹莓派街機 | LCTT x X-CMD","titleTemplate":false,"description":"給那些懷舊的遊戲骨灰粉絲們：自制一台樹莓派街機 | LCTT (201411) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"給那些懷舊的遊戲骨灰粉絲們：自制一台樹莓派街機 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"給那些懷舊的遊戲骨灰粉絲們：自制一台樹莓派街機 | LCTT (201411) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201411/20140819 Build a Raspberry Pi Arcade Machine","title":"給那些懷舊的遊戲骨灰粉絲們：自制一台樹莓派街機","tag":"201411","desc":""},"relativePath":"201411/20140819 Build a Raspberry Pi Arcade Machine.md","filePath":"[post].md"}'),M={name:"201411/20140819 Build a Raspberry Pi Arcade Machine.md"};function c(m,a,u,A,P,h){const t=r("Link");return s(),d("div",null,[a[16]||(a[16]=o('<h1 id="給那些懷舊的遊戲骨灰粉絲們-自制一台樹莓派街機" tabindex="-1">給那些懷舊的遊戲骨灰粉絲們：自制一台樹莓派街機 <a class="header-anchor" href="#給那些懷舊的遊戲骨灰粉絲們-自制一台樹莓派街機" aria-label="Permalink to “給那些懷舊的遊戲骨灰粉絲們：自制一台樹莓派街機”">​</a></h1><p><strong>利用當代神奇設備來重温80年代的黃金記憶。</strong></p><h3 id="你需要以下硬件" tabindex="-1">你需要以下硬件 <a class="header-anchor" href="#你需要以下硬件" aria-label="Permalink to “你需要以下硬件”">​</a></h3><ul><li>一台樹莓派以及一張4GBSD卡</li><li>一台支持HDMI的LCD顯示屏</li><li>遊戲手柄或者...</li><li>一個JAMMA街機遊戲機外殼機箱</li><li>J-Pac或者I-Pac</li></ul><p>80年代有太多難忘的記憶；冷戰結束，Quatro碳酸飲料，Korg Polysix合成器，以及Commodore 64家用電腦。但對於某些年輕人來説，這些都沒有街機遊戲機那樣有説服力，或那種甜蜜的叛逆。籠罩着煙味和此起彼伏的8比特音效，它們就是在擠出來的時間裏去探索的洞穴：50分錢和一個遊戲幣能讓你消耗整個午餐時間，在這些遊戲上磨練着你的技能：小蜜蜂，城市大金剛，蜈蚣，行星射擊，吃豆小姐，火鳳凰，R-Rype，大金剛，雷霆計劃，鐵手套，街頭霸王，超越賽車，防衞者爭戰...噢，這個列表太長了。</p><p>這些遊戲，以及玩這些遊戲的街機機器，仍然像30年前那樣有吸引力。不像年輕時候那樣，現在可以不用裝一兜零錢就能玩了，最終讓你超越那些有錢的孩子以及他們無休止的‘繼續遊戲’。所以是時候打造一個你自己的基於Linux的街機遊戲機了，然後挑戰一下過去的最高分。</p><p>我們將會包括所有的步驟，來將一個便宜的街機遊戲機器外殼變成一台Linux驅動的多平台復古遊戲系統。但是這並不意味着你就一定要搭建一個同樣的系統。比如説，你可以放棄那個又大又重還有潛在致癌性外殼的箱子本身，而是將內部控制核心裝進一箇舊遊戲主機或同等大小的盒子裏。或者説，你也可以簡單地放棄小巧的樹莓派，而將系統的大腦換成一台更強勁的Linux主機。舉個例子，它可以作為運行SteamOS的一個理想平台，用來玩那些更優秀的現代街機遊戲。</p><p>在之後的幾個頁面裏，我們將搭建一台基於樹莓派的街機遊戲機，你應該也能從其中發現很多點子應用到你自己的項目上，即使它們和我們這個項目不太一樣。然後因為我們是用無比強大的MAME來做這件事情，你幾乎可以讓它在任意平台上運行。</p><p><img src="http://www.linuxvoice.com/wp-content/uploads/2014/08/picade3.png" alt=""></p><p><em>我們是在B+型號出來以前完成的這個項目。它應該也可以同樣工作在更新的主板上，你應該不用一個帶電源的USB Hub也可以</em></p><h3 id="聲明" tabindex="-1">聲明 <a class="header-anchor" href="#聲明" aria-label="Permalink to “聲明”">​</a></h3><p>強調一下，我們搗騰的電子器件可能會讓你受到電擊。請確保你做的任何改動都是有資質的電子工程師幫你檢查過的。我們也不會深入討論如何獲取遊戲，但是有很多合法的資源，例如基於MAME模擬器的老遊戲，以及較新的商業遊戲。</p><h4 id="第一步-街機機櫃" tabindex="-1">第一步：街機機櫃 <a class="header-anchor" href="#第一步-街機機櫃" aria-label="Permalink to “第一步：街機機櫃”">​</a></h4><p>街機機櫃本身就是最大的挑戰。我們在eBay上淘了個二手的90年代初的雙人泡泡龍游戲機。然後花了£220裝在一台旅行車後面送過來。類似這種機櫃的價格並不確定。我們看到過很多在£100以內的。而另一方面，還有很多人願意花數千塊錢去買原版側面貼紙完整的機器。</p><p>決定買一個街機機櫃，主要有兩個考慮。第一個是它的體積：這東西又大又重。又佔地方，而且需要至少兩個人才能搬動。如果你不缺錢的話，還可以買DIY機櫃或者全新的小一點的，例如適合擺在桌子上的那種。然後，酒櫃也能很合適。</p><p><img src="http://www.linuxvoice.com/wp-content/uploads/2014/08/picade4.jpg" alt=""></p><p><em>這種機櫃可能很便宜，但是他們都很重。不要一個人去搬。一些更古老的機器可能還會需要一點小關懷，例如重新噴個漆以及一些修理工作</em></p><p>除了獲得更加真實的遊戲體驗以外，購買原版的街機機櫃的一個絕佳理由是可以使用原版的控制器。從eBay上買到的大多數機器都支持兩個人同時玩，有兩個搖桿以及每個玩家各自的一些按鈕，再加上玩家一和玩家二的選擇按鈕。為了兼容更多遊戲，我們建議您找一台每個玩家都有6個按鍵的型號，這個是通用配置。也許你還想看看支持超過兩位玩家的控制台，或者有空間放其他遊戲控制器的，比如説街機軌跡球（類似瘋狂彈珠這種遊戲需要的），或者一個旋鈕（打磚塊）。這些待會都可以輕鬆裝上去，因為有現成的現代USB設備。</p><p>控制器是第二考慮的，而且我們認為是最重要的，因為要通過它把你的搖動和拍打轉變成遊戲裏的動作。當你準備買一個機櫃時需要考慮一種叫JAMMA的東西，它是日本娛樂機械製造商協會（Japan Amusement Machinery Manufacturers Association）的縮寫。JAMMA是街機遊戲機裏的行業標準，定義了包含遊戲芯片的電路板和遊戲控制器的連接方式，以及投幣機制。它是一個連接兩個玩家的搖桿和按鈕的所有線纜的接口電路，把它們統一到一個標準的連接頭。JAMMA就是這個連接頭的大小以及引腳定義，這就意味着不管你安裝的主板是什麼，按鈕和控制器都將會連接到相同功能接口，所以街機的主人只需要再更換下機櫃上的外觀圖片，就可以招攬新玩家了。</p><p>但是首先，提醒一下：JAMMA連接頭上帶有12V電壓供電，通常由大多數街機裏都有的電源模組供給。為了避免意外短路或是不小心掉個螺絲刀什麼的造成損壞，我們完全切斷了這個供電。在本教程後面的任何階段，我們也不會用到這個連接頭上的任何電源腳。</p><p><img src="http://www.linuxvoice.com/wp-content/uploads/2014/08/picade2.png" alt=""></p><h4 id="第二步-j-pac" tabindex="-1">第二步：J-PAC <a class="header-anchor" href="#第二步-j-pac" aria-label="Permalink to “第二步：J-PAC”">​</a></h4>',22)),n("p",null,[a[1]||(a[1]=e("有一點非常方便，你可以買到這樣一種設備，連接街機機櫃裏的JAMMA接頭和電腦的USB端口，將機櫃上的搖桿和按鍵動作都轉換成（可配置的）鍵盤命令，它們可以在Linux裏用來控制任何想玩的遊戲。這個設備就叫J-Pac（",-1)),p(t,{href:"http://www.ultimarc.com/jpac.html"},{default:i(()=>[...a[0]||(a[0]=[e("www.ultimarc.com/jpac.html",-1)])]),_:1}),a[2]||(a[2]=e(" – 大概£54）。",-1))]),a[17]||(a[17]=o(`<p>它最大的特點不是它的連接性；而是它處理和轉換輸入信號的方式，因為它比標準的USB手柄強太多太多了。每一個輸入都有自己獨立的中斷，而且沒有限制同時按下或按住的按鈕或搖桿方向的數量。這對於類似街頭霸王的遊戲來説非常關鍵，因為他們依賴於同時迅速按下的組合鍵，而且用來對那些發飆後按下自己所有按鍵的不良對手發出致命一擊時也必不可少。許多其他控制器，特別是那些生成鍵盤輸入的，受到了他們所採用的USB控制器的同時六個輸入的限制，以及一堆的Alt，Shift和Ctrl鍵的特殊處理的限制。J-Pac還可以接入傾角傳感器，甚至某些投幣裝置，不用預先配置就可以在Linux下工作了。</p><p>另外的選擇是一個類似的叫I-Pac的設備。它做了和J-Pac相同的事情，只不過不支持JAMMA接頭。這意味着你不能把JAMMA控制器接上去，但同時也就是説你可以設計你自己的控制器佈局，再把每個控制接到I-Pac上去。這對第一個項目來説也許有點小難，但是這卻是許多街機迷們選擇的方式，特別是他們想設計一個支持四個玩家的控制板的時候，或者是一個整合許多不同類型控制的面板的時候。我們採用的方式並不是我們推薦必須要做的，我們改造了一個輸入有問題的二手X-Arcade Tankstick控制面板，換上了新的搖桿和按鈕，再接到新的JAMMA接口，這樣有一個非常好的地方就是可以用便宜的價格（£8）買到所有用到的線材包括電路板邊緣插頭。</p><p><img src="http://www.linuxvoice.com/wp-content/uploads/2014/08/picade5.jpg" alt=""></p><p><em>上圖是我們已經裝到機櫃上的J-Pac。右邊的藍色和紅色導線接到我們的機櫃上額外的1號和2號玩家按鈕</em></p><p>不管你選擇的是I-Pac或是J-Pac，它們產生的按鍵都是MAME的默認值。也就是説運行模擬器之後不需要手動調整輸入。例如玩家1，會默認將鍵盤方向鍵映射成上下左右，以及將左邊的Ctrl，左邊的ALT，空格和左邊的Shift鍵映射到按鈕1-4。但是真正實用的功能是，對於我們來説，是雙鍵快捷方式。當按下並按住玩家1按鈕後，就可以通過把玩家1的搖桿拉到下的位置發出用來暫停遊戲的P按鍵，推到上的位置調整音量，以及推到右的位置來進入MAME自己的設置界面。這些特殊組合鍵設計的很巧妙，不會對正常玩遊戲帶來任何干擾，因為他們只有在按住玩家1按鈕後才會生效，然後可以讓你正在運行遊戲的時候也能做任何需要的事情。例如，你可以完全地重新配置MAME，使用它自己的菜單，在玩遊戲的時候改變輸入綁定和靈敏度。</p><p>最後，按住玩家1按鈕然後按下玩家2按鈕就可以退出MAME，如果你使用了啓動菜單或MAME管理器的話就很有用了，因為他們會自動啓動遊戲，然後你就可以用最快的速度開始玩另一個遊戲了。</p><p>對於顯示屏我們採取了比較保守的方式，拿掉了街機原裝的笨重的而且已經壞掉的CRT，換成一個低成本的LCD顯示器。這樣做有很多好處。首先，這個顯示器有HDMI接口，這樣他就可以輕易地直接連接到樹莓派或是現代的顯卡上。第二，你也不用去設定驅動街機屏幕所需要的低頻率刷新模式，也不需要驅動它的專用圖形硬件。第三，這也是最安全的方式，因為街機屏幕往往在機身背後沒有保護措施，讓很高的電壓離你的手只有幾英寸的距離。也不是説你完全不能用CRT，如果那就是你追求的體驗的話 – 這也是獲得所追求的遊戲體驗的最真實的方式，但是我們在軟件裏充分細調了CRT模擬部分，我們對輸出已經很滿意了，而且不需要用那個古老的CRT更是讓我們高興。</p><p>你也許還需要考慮用一個老式的4:3長寬比的LCD，而不是那種寬屏的現代產品，因為4:3模式用來玩豎屏或橫屏的遊戲更實用。比如説玩豎屏的射擊遊戲，例如雷電，如果使用寬屏顯示器的話，會在屏幕兩邊都有一個黑條。這些黑條一般會用來顯示一些遊戲指引，或者你也可以把屏幕翻轉90度，這樣就可以用上每個像素了，但這卻不實用，除非你只玩豎屏遊戲或者有一個容易操作的旋轉支座。</p><p>裝載顯示屏也很重要。如果你拿掉了CRT的話，沒有現成的地方安裝LCD。我們的方式是買了一些中密度纖維板(MDF)並切割成適合原來擺放CRT的地方。固定以好，我們把一個便宜的VESA支座放在中間。VESA底座可以用來掛載大多數屏幕，大的或小的。最後，因為我們的機櫃前面有煙玻璃，我們必須保證亮度和對比度都設置的足夠高。</p><h3 id="第三步-裝配" tabindex="-1">第三步：裝配 <a class="header-anchor" href="#第三步-裝配" aria-label="Permalink to “第三步：裝配”">​</a></h3><p>現在幾個硬件大件都選好了，而且也基本上確定了最終街機機櫃要擺放的地方，把這幾個配件裝到一起並沒有太大難度。我們安全地把機櫃後面的電源輸入部分拆開，然後在背後的空間接了一個符合插座。接在了電源開關之後的電線上。</p><p>幾乎所有的街機機櫃右上角都有個電源開關，但通常在機櫃靠下一點的地方有大量的導線鉸接在它上面，也就是説我們的設備可以使用普通的電源連接頭。我們的機櫃上還有一個熒光管，用做機器上邊燈罩的背光，之前是直接連接到電源上的，我們可以用一個普通插頭讓它保持和電源連接。當你打開機櫃上的電源開關的時候，電流會流入機櫃裏的各個部件 - 你的樹莓派和顯示屏都會開機，所有一切就都準備好了。</p><p>J-Pac模組直接插到JAMMA接口上，但你可能還需要一點手動調整。標準的JAMMA只支持每個玩家最多三個按鍵（儘管許多非正式的支持四個），而J-Pac可以支持六個。為了連接額外的按鈕，你需要把按鈕開關的一端接到J-Pac的GND上，另一端接到J-Pac板邊有螺絲固定的輸入上。它們被標記成1SW4，1SW5，1SW6，2SW4，2SW5和2SW6。J-Pac也有聲音的直通連接，但是我們發現雜音太多沒法用。改成把機櫃上的喇叭連接到一個二手的SoundBlaster功放上，再接到樹莓派的音頻輸出端口。聲音不一定要純正，但音量一定要足夠大。</p><p><img src="http://www.linuxvoice.com/wp-content/uploads/2014/08/picade6.jpg" alt=""></p><p><em>我們的樹莓派已經接到J-Pac左邊，也已經連接了顯示屏和USB hub</em></p><p>然後把J-Pac或I-Pac模組通過PS2轉USB連接線接到你的PC或樹莓派，也可以直接接到PC的PS2接口。要用舊的PS2接頭的話額外還有個要求，你的電腦得足夠古老還有這個，但是我們測試發現用USB性能是一樣的。當然，這個不能用於不帶PS2的樹莓派，而且別忘了樹莓派也需要供電。我們一般建議使用一個帶電源的USB hub，因為沒有供電是樹莓派不工作最常見的錯誤。你還需要保證樹莓派的網絡正常，要麼通過以太網（也許使用一個藏到機櫃裏的電力線適配器），或者通過無線USB設備。網絡很關鍵是因為在樹莓派被藏到機櫃裏後你還可以重新配置它，不用接鍵盤或鼠標就可以讓你調整設置以及執行管理任務。</p><blockquote><h3 id="投幣裝置" tabindex="-1">投幣裝置 <a class="header-anchor" href="#投幣裝置" aria-label="Permalink to “投幣裝置”">​</a></h3></blockquote><blockquote><p>在街機模擬社區裏，讓投幣裝置工作在模擬器上工作就會和商業產品太接近了。這就意味着你有潛在的可能對使用你機器的人收取費用。這不僅僅只是不正當，考慮到運行在你自己街機上的那些遊戲的來源，這將會是非法的。這很顯然違背了模擬的精神。不過，我們和其他熱愛者覺得一個能工作的投幣裝置更進一步地靠近了街機的真實，而且值得付出努力來營造對那個過去街機的懷念。丟個10便士硬幣到投幣口然後再聽到機器發出增加點數的聲音，沒有什麼比得上這種感受了。</p></blockquote><blockquote><p>實際上難度也不大。取決於你街機上的投幣裝置，以及它如何發信號通知投了幾個幣。大多數投幣裝置分為兩個部分。較大的一部分是硬幣接收和驗證裝置。這是投幣過程的物理部分，用於檢測硬幣是否真實以及確定它的價值。這是通過一個遊戲點數邏輯電路板來實現的，通常用一個排線連接，上邊還帶有很多DIP開關。這些開關用來決定接受哪種硬幣，以及一個硬幣能產生多少點數。然後就是簡單地找到輸出開關，每個點數都會觸發它一次，然後把它接到JAMMA連接頭的投幣輸入上，或者直接接到J-Pac。我們的投幣裝置型號是Mars MS111，在90年代早期的英國很常見，網上有大量關於每個DIP開關作用的信息，也有如何重新編程控制器來接受新硬幣的方法。我們還能在這個裝置的12V上接個小燈用來照亮投幣孔。</p></blockquote><h4 id="第四步-軟件" tabindex="-1">第四步：軟件 <a class="header-anchor" href="#第四步-軟件" aria-label="Permalink to “第四步：軟件”">​</a></h4><p>MAME是這種規模項目唯一可行的模擬器，它如今支持運行在數不清的不同平台上的各種各樣的遊戲，從第一代街機到一些最近的機器。從這個項目中還孕育出了MESS，一個多模擬器的超級系統，針對的平台是80到90年代的家庭電腦以及電視遊戲機。</p><p>如何配置MAME本身都可以寫上六頁的文章了。它是一個複雜的，無序的，偉大的軟件程序，模擬瞭如此之多的CPU，聲卡，芯片，控制器以及那麼多的選項，就像MythTV，你都永遠不能真正配置好它。</p><p>但是也有個相對省事的方式，一個特別為樹莓派構建的版本。它叫PiMAME。它是一個可下載的發佈版和腳本，基於Raspbian，這是樹莓派的默認發佈版。它不僅僅會把MAME裝到樹莓派上（這很有用因為沒有哪個默認倉庫裏有這個），還會安裝其他一些精選出來的模擬器，並通過一個前端來管理他們。MAME，舉個例子，是一個有數十個參數的命令列應用。但是PiMAME還有一個妙招 - 它安裝了一個簡單的網頁服務器，可以在連接上網絡後讓你通過瀏覽器來安裝新遊戲。這是一個很好的優點，因為把遊戲文件放到正確的目錄下是使用MAME的困難之一，這還能讓你連接到樹莓派的存儲設備得到最優使用。還有，PiMAME會通過用來安裝它的腳本更新自己，所以保持最新版本就太簡單了。目前來説這個非常有用，因為在編寫這個項目的時候，正好在0.8版這樣一個重大更新發布的時間點上。我們在三月份早期時發現有一些輕微的不穩定，但是我們確定在你讀到這篇文章的時候一切都會解決。</p><p>安裝PiMAME最好的方式就是先裝Raspbian。你可以通過NOOBS安裝，使用電腦上的圖形工具，或者通過dd命令把Raspbian的內容直接寫入到你的SD卡中。就像我們上個月的BrewPi教程裏曾提到的，這個過程在之前已經被記錄過很多次，所以就不再浪費口水了。想簡單點就裝一下NOOBS，參照樹莓派網站上的指引。在裝好Raspbian並跑起來以後，請確保使用配置工具來釋放SD卡上的空間，以及確保系統已經更新到最新（<code>sudo apt-get update; sudo apt-get upgrade</code>）。然後再確保已經安裝好了git工具包。當前任意Raspbian版本都會自帶git，不過你仍然可以通過命令<code>sudo apt-get install git</code>檢查一下。</p><p>然後再在終端裏輸入下面的命令把PiMAME安裝器從項目的GitHub倉庫克隆到本地：</p><pre><code>git clone https://github.com/ssilverm/pimame_installer
</code></pre><p>之後，如果命令工作正常的話你應該能看到如下的反饋輸出：</p><pre><code>Cloning into ‘pimame_installer’...
remote: Reusing existing pack: 2306, done.
remote: Total 2306 (delta 0), reused 0 (delta 0)
Receiving objects: 100% (2306/2306), 4.61 MiB | 11 KiB/s, done.
Resolving deltas: 100% (823/823), done.
</code></pre><p>這個命令會創建一個叫‘pimame_installer’的新目錄，然後下一步就是進入這個目錄再執行它裏面的腳本：</p><pre><code>cd pimame_installer/
sudo ./install.sh
</code></pre><p>這個命令會安裝和配置很多軟件。所需的時間長短也取決於你的因特網速度，因為需要下載大量的包。我們那個簡陋的樹莓派加15Mb因特網連接用了差不多45分鐘來執行完這個腳本，在這之後你會收到重啓機器的提示。你現在可以安全的通過輸入<code>sudo shutdown -r</code>來重啓了，因為這個命令會自動處理剩下的SD卡寫入操作。</p><p>這就是安裝的全部事情了。在重啓樹莓派後，就會自動登錄，然後會出現PiMAME啓動菜單。在0.8版本里這是個非常漂亮的界面，有每個支持平台的圖片，還有紅色圖標提示已經安裝了多少個遊戲。現在應該可以用控制器來操作了。如果需要檢查控制器是否正確連接，可以用SSH連接到樹莓派然後檢查一下文件<strong>/dev/input/by-id/usb-Ultimarc_I-PAC_Ultimarc_I-PAC-event-kbd</strong>是否存在。</p><p>默認的按鍵配置就可以讓你選擇要在你的街機上運行哪個模擬器。我們最感興趣的就是第一個，名字叫‘AdvMAME’，不過你也許會很驚訝看到還有一個MAME可選的，MAME4ALL。MAME4ALL是特別為樹莓派構建的，使用了舊版的MAME源代碼，所以它所支持的ROMS的性能也是最佳的。這是很合理的，因為你的樹莓派不可能玩那些要求很高的遊戲，所以沒有理由苛求模擬器的沒必要的兼容性。現在剩下的事情就是找些遊戲裝到你的系統裏（參考下面的方法），然後盡情享受吧！</p><p><img src="http://www.linuxvoice.com/wp-content/uploads/2014/08/picade1.png" alt=""></p><hr>`,35)),n("p",null,[a[4]||(a[4]=e("via: ",-1)),p(t,{href:"http://www.linuxvoice.com/arcade-machine/"},{default:i(()=>[...a[3]||(a[3]=[e("http://www.linuxvoice.com/arcade-machine/",-1)])]),_:1})]),n("p",null,[a[8]||(a[8]=e("作者：",-1)),p(t,{href:"http://www.linuxvoice.com/author/ben_everard/"},{default:i(()=>[...a[5]||(a[5]=[e("Ben Everard",-1)])]),_:1}),a[9]||(a[9]=e(" 譯者：",-1)),p(t,{href:"https://github.com/zpl1025"},{default:i(()=>[...a[6]||(a[6]=[e("zpl1025",-1)])]),_:1}),a[10]||(a[10]=e(" 校對：",-1)),p(t,{href:"https://github.com/wxy"},{default:i(()=>[...a[7]||(a[7]=[e("wxy",-1)])]),_:1})]),n("p",null,[a[13]||(a[13]=e("本文由 ",-1)),p(t,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...a[11]||(a[11]=[e("LCTT",-1)])]),_:1}),a[14]||(a[14]=e(" 原創翻譯，",-1)),p(t,{href:"http://linux.cn/"},{default:i(()=>[...a[12]||(a[12]=[e("Linux中國",-1)])]),_:1}),a[15]||(a[15]=e(" 榮譽推出",-1))])])}const g=l(M,[["render",c]]);export{w as __pageData,g as default};
